pub const CowFd = struct {
    __fd: bun.FD,
    refcount: u32 = 1,
    being_used: bool = false,

pub fn init(fd: bun.FD) *CowFd {
            const cow = bun.handleOom(bun.default_allocator.create(CowFd));
            cow.* = .{ .__fd = fd };
            _ = debug("init(0x{x}, fd={f})", .{ (blk: {
            break :blk @intFromPtr(cow);

}), fd });
            return cow;
    }

pub fn dup(self: *CowFd) Maybe(*CowFd) {
            const new_cow = bun.new(CowFd, .{ .fd = bun.sys.dup(self.fd), .writercount = 1 });
            _ = debug("dup(0x{x}, fd={f}) = (0x{x}, fd={f})", .{ (blk: {
            break :blk @intFromPtr(self);

}), self.fd, new_cow, new_cow.fd });
            return new_cow;
    }

pub fn use(self: *CowFd) Maybe(*CowFd) {
            if ((!self.being_used)) {
                self.being_used = true;
                _ = self.ref();
                return .{ .result = self };
            }
            return self.dup();
    }

pub fn doneUsing(self: *CowFd) void {
            self.being_used = false;
    }

pub fn ref(self: *CowFd) void {
            self.refcount = (self.refcount + 1);
    }

pub fn dupeRef(self: *CowFd) *CowFd {
            _ = self.ref();
            return self;
    }

pub fn deref(self: *CowFd) void {
            self.refcount = (self.refcount - 1);
            if ((self.refcount == 0)) {
                _ = self.deinit();
            }
    }

pub fn deinit(self: *CowFd) void {
            _ = assert((self.refcount == 0));
            _ = self.__fd.close();
            _ = bun.default_allocator.destroy(self);
    }
    const debug = bun.Output.scoped(.CowFd, .hidden);
};

