pub fn deinit(self: *@This()) Yield {
            if (comptime bun.Environment.allow_assert) {
                _ = assert((self.state == .done));
            }
            _ = log("OutputTask({s}, 0x{x}) deinit", .{ @typeName(Parent), @intFromPtr(self) });
            var _task_guard = OutputTaskDeinitGuard(@This()){ .task = self };
            _ = &_task_guard;
            var ___task_guard_moved = false; _ = &___task_guard_moved;
            defer if (!___task_guard_moved) { ___task_guard_moved = true; const __T = @TypeOf(_task_guard); if (@typeInfo(__T) == .optional) { if (_task_guard) |__cp_opt_v| { const __OptT = @TypeOf(__cp_opt_v); if (@typeInfo(__OptT) == .pointer and @typeInfo(__OptT).pointer.size == .one and (if (@hasField(@TypeOf(@typeInfo(__OptT).pointer), "is_const")) !@typeInfo(__OptT).pointer.is_const else !@typeInfo(__OptT).pointer.attrs.@"const")) { const __CpChild = @typeInfo(__OptT).pointer.child; if (@typeInfo(__CpChild) == .@"struct" and @hasDecl(__CpChild, "__cp_deinit")) { __cp_opt_v.__cp_deinit(); } } else if (@typeInfo(__OptT) == .@"struct" and @hasDecl(__OptT, "__cp_deinit")) { var _drop_val = __cp_opt_v; _drop_val.__cp_deinit(); } } } else if (@typeInfo(__T) == .pointer and @typeInfo(__T).pointer.size == .one and (if (@hasField(@TypeOf(@typeInfo(__T).pointer), "is_const")) !@typeInfo(__T).pointer.is_const else !@typeInfo(__T).pointer.attrs.@"const")) { const __CpChild = @typeInfo(__T).pointer.child; if (@typeInfo(__CpChild) == .@"struct" and @hasDecl(__CpChild, "__cp_deinit")) { _task_guard.__cp_deinit(); } } else if (@typeInfo(__T) == .@"struct" and @hasDecl(__T, "__cp_deinit")) { var _drop_val = _task_guard; _drop_val.__cp_deinit(); } };
            return vtable.onDone(self.parent);
    }

pub fn start(self: *@This(), errbuf: OutputTaskErrBuf) Yield {
            _ = log("OutputTask({s}, 0x{x}) start errbuf={s}", .{ @typeName(Parent), @intFromPtr(self), (if ((errbuf != null)) errbuf.?[0..@min(128, errbuf.?.len)] else "null") });
            self.state = .waiting_write_err;
            if ((errbuf != null)) {
                const e = errbuf.?;
                const y_err = vtable.writeErr(self.parent, self, e);
                if ((y_err != null)) {
                    return y_err.?;
                }
                return self.next();
            }
            self.state = .waiting_write_out;
            const y_out = vtable.writeOut(self.parent, self, (&self.output));
            if ((y_out != null)) {
                return y_out.?;
            }
            _ = vtable.onWriteOut(self.parent);
            self.state = .done;
            return self.deinit();
    }

pub fn next(self: *@This()) Yield {
            switch (self.state) {
.waiting_write_err => {
_ = vtable.onWriteErr(self.parent);
            self.state = .waiting_write_out;
            const y_out = vtable.writeOut(self.parent, self, (&self.output));
            if ((y_out != null)) {
                return y_out.?;
            }
            _ = vtable.onWriteOut(self.parent);
            self.state = .done;
            return self.deinit();
},
.waiting_write_out => {
_ = vtable.onWriteOut(self.parent);
            self.state = .done;
            return self.deinit();
},
.done => {
_ = @panic("Invalid state");
},
}
    }

pub fn onIOWriterChunk(self: *@This(), _: usize, e: OutputTaskSysErr) Yield {
            _ = log("OutputTask({s}, 0x{x}) onIOWriterChunk", .{ @typeName(Parent), @intFromPtr(self) });
            if ((e != null)) {
                _ = e.?.deref();
            }
            switch (self.state) {
.waiting_write_err => {
_ = vtable.onWriteErr(self.parent);
            self.state = .waiting_write_out;
            const y_out = vtable.writeOut(self.parent, self, (&self.output));
            if ((y_out != null)) {
                return y_out.?;
            }
            _ = vtable.onWriteOut(self.parent);
            self.state = .done;
            return self.deinit();
},
.waiting_write_out => {
_ = vtable.onWriteOut(self.parent);
            self.state = .done;
            return self.deinit();
},
.done => {
_ = @panic("Invalid state");
},
}
    }
};
}

pub fn unsupportedFlag(comptime name: []const u8) []const u8 {
        return (("unsupported option, please open a GitHub issue -- " ++ name) ++ "\n");
}

pub fn FlagParser(comptime Opts: type) type {
        return struct {

pub fn parseFlags(opts: Opts, args: []const CStr) Result(FlagArgs, ParseError) {
            var idx: usize = 0;
            _ = &idx;
            if ((args.len == 0)) {
                return .{ .ok = null };
            }
            while ((idx < args.len)) : (idx = (idx + 1)) {
                const flag = args[@as(usize, @intCast(idx))];
                switch (parseFlag(opts, flag[0..std.mem.len(flag)])) {
.done => {
const filepath_args = args[idx..];
                return .{ .ok = filepath_args };
},
.continue_parsing => {

},
.illegal_option => |opt_str| {
return .{ .err = .{ .illegal_option = opt_str } };
},
.unsupported => |unsp| {
return .{ .err = .{ .unsupported = unsp } };
},
.show_usage => {
return .{ .err = .show_usage };
},
}
            }
            return .{ .err = .show_usage };
    }

pub fn parseFlag(opts: Opts, flag: []const u8) ParseFlagResult {
            if ((flag.len == 0)) {
                return .done;
            }
            if ((flag[0] != 45)) {
                return .done;
            }
            if ((flag.len == 1)) {
                return .{ .illegal_option = "-" };
            }
            if (((flag.len > 2) and (flag[1] == 45))) {
                if (opts.parseLong(flag)) |result| {
                    _ = &result;
                    return result;
                }
            }
            const small_flags = flag[1..];
            for (small_flags, 0..) |char, i| {
                _ = &char;
                _ = &i;
                if (opts.parseShort(char, small_flags, i)) |e| {
                    _ = &e;
                    return e;
                }
            }
            return .continue_parsing;
    }
    pub const Result = _ResultMod.Result;
};
}

pub fn isPollable(fd: bun.FD, mode: bun.Mode) bool {
        return (switch (bun.Environment.os) {
.windows, .wasm => false,
.linux, .freebsd => ((posix.S.ISFIFO(mode) or posix.S.ISSOCK(mode)) or posix.isatty(fd.native())),
.mac => (if (posix.S.ISREG(mode)) false else ((posix.S.ISFIFO(mode) or posix.S.ISSOCK(mode)) or posix.isatty(fd.native()))),
});
}

pub fn isPollableFromMode(mode: bun.Mode) bool {
        return (switch (bun.Environment.os) {
.windows, .wasm => false,
.linux, .freebsd => (posix.S.ISFIFO(mode) or posix.S.ISSOCK(mode)),
.mac => (if (posix.S.ISREG(mode)) false else (posix.S.ISFIFO(mode) or posix.S.ISSOCK(mode))),
});
}

pub fn unreachableState(context: []const u8, state: []const u8) noreturn {
        @branchHint(.cold);
        return bun.Output.panic("Bun shell has reached an unreachable state \"{s}\" in the {s} context. This indicates a bug, please open a GitHub issue.", .{ state, context });
}
